def durand(coeffs, iters, damp=1.0):
    n=len(coeffs)-1
    R=1.0+max(abs(c) for c in coeffs[1:])
    print('R',R)
    zs = R*np.exp(2j*np.pi*np.arange(n)/n).astype(np.complex128)
    zs += 0.1
    for it in range(iters):
        pz=np.zeros(n,dtype=np.complex128)
        for i,z in enumerate(zs):
            val=complex(coeffs[0])
            for c in coeffs[1:]:
                val=val*z+complex(c)
            pz[i]=val
        denom=np.ones(n,dtype=np.complex128)
        for i in range(n):
            for j in range(n):
                if i!=j:
                    denom[i] *= (zs[i]-zs[j])
        delta=np.zeros(n,dtype=np.complex128)
